/bin/bash -lc "cat <<'EOF' > app/page.tsx
import { cacheTag, revalidateTag } from 'next/cache';

import { getAllProducts } from '@/lib/db';

type Product = {
  id: number;
  name: string;
  price: number;
};

async function ProductsList() {
  'use cache';
  cacheTag('products');

  const products = (await getAllProducts()) as Product[];
  const cachedAt = new Date().toISOString();

  return (
    <section>
      <div>
        <strong>Cached snapshot:</strong> {cachedAt}
      </div>
      <ul>
        {products.map(product => (
          <li key={product.id}>
            {product.name} - "'${product.price}
          </li>
        ))}
      </ul>
    </section>
  );
}

export default function Page() {
  return (
    <div>
      <h1>Product Listing</h1>
      <p>
        The list below is cached with the <code>products</code> tag. Submit the
        form to invalidate the cache after a simulated data update.
      </p>
      <form
        action={async () => {
          '"'use server';
          // Simulate a data mutation, then invalidate cached reads.
          // await updateProducts();
          revalidateTag('products');
        }}
      >
        <button type=\"submit\">Invalidate Products Cache</button>
      </form>
      <ProductsList />
    </div>
  );
}
EOF"
